package `in`.hinducalendar.hindu_calendar

import java.io.ByteArrayOutputStream

/** Add links to the PDF generated by Android, without rasterising its pages.
 * Incremental update retains the original content streams and embedded fonts. */
object CalendarPdfLinks {
    fun addFooterLinks(bytes: ByteArray, url: String): ByteArray {
        require(url == CalendarVectorPdf.STORE_URL)
        val original = bytes.toString(Charsets.ISO_8859_1)
        val previous = Regex("startxref\\s+(\\d+)\\s+%%EOF").findAll(original).last().groupValues[1]
        val root = Regex("/Root\\s+(\\d+\\s+\\d+\\s+R)").findAll(original).last().groupValues[1]
        val size = Regex("/Size\\s+(\\d+)").findAll(original).last().groupValues[1].toInt()
        val pages = Regex("(?m)^(\\d+) 0 obj\\s*(<<[\\s\\S]*?)endobj").findAll(original)
            .filter { Regex("/Type\\s*/Page(?:\\s|/|>)").containsMatchIn(it.groupValues[2]) }.toList()
        require(pages.size == 1 || pages.size == 12) { "PDF page tree was not readable" }
        val output = ByteArrayOutputStream().apply { write(bytes); write('\n'.code) }
        val offsets = sortedMapOf<Int, Int>()
        fun add(id: Int, body: String) {
            offsets[id] = output.size()
            output.write("$id 0 obj\n$body\nendobj\n".toByteArray(Charsets.ISO_8859_1))
        }
        pages.forEachIndexed { i, page ->
            val annotation = size+i
            val body = page.groupValues[2].trimEnd()
            require(body.endsWith(">>"))
            add(page.groupValues[1].toInt(), body.dropLast(2)+" /Annots [$annotation 0 R] >>")
            add(annotation,"<< /Type /Annot /Subtype /Link /Rect [18 12 577 122] /Border [0 0 0] /A << /S /URI /URI ($url) >> >>")
        }
        val xref = output.size()
        output.write("xref\n".toByteArray())
        offsets.forEach { (id, offset) ->
            output.write("$id 1\n${offset.toString().padStart(10,'0')} 00000 n \n".toByteArray())
        }
        output.write("trailer\n<< /Size ${size+pages.size} /Root $root /Prev $previous >>\nstartxref\n$xref\n%%EOF\n".toByteArray())
        return output.toByteArray()
    }
}
